"""A class for obtaining the Linac software build version and Linac head type information"""

from interops.libraries.miscellaneous.registry_functions import getRegistryValue_cmd_version
import logging
from interops.libraries.desktop.configuration import Config
import interops.libraries.desktop.config_constants as cfg
import os
import sys

# Get the current python installation path
python_install_path = sys.exec_prefix
sharedconfig_path = os.path.abspath(os.path.join(
    python_install_path, cfg.DEFAULT_SHAREDCONFIG_PATH))
# Load the sharedconfig.cfg file
Config.load(sharedconfig_path)
squish_bin_path = Config.get("system.squish_bin", cfg.DEFAULT_DEV_SQUISH_BIN_PATH)
squish_python_lib_path = Config.get("system.squish_python_lib", cfg.DEFAULT_DEV_SQUISH_LIB_PATH)
sys.path.extend([squish_bin_path, squish_python_lib_path])
import test

logger = logging.getLogger(__name__)


class Linac():
    # ToT=Yes
    def __init__(self, run_mode="None"):
        logger.debug("init Linac")

        ip_addr = Config.get("attach.host")
        port = Config.get("attach.port")
        self.linac_id = getRegistryValue_cmd_version(
            r"SOFTWARE\Elekta Oncology Systems Ltd\Linac", "LinacId", ip_addr, int(port)).strip('\n')
        # Note: commented out test.log and replaced with logger.info to remove dependency on squishtest.setTestResult()
        #test.log("linac_id " + self.linac_id)   # type: ignore
        logger.info("linac_id " + self.linac_id)
        self.build = getRegistryValue_cmd_version(
            r"SOFTWARE\Elekta Oncology Systems Ltd\RTD", "Build", ip_addr, int(port)).strip('\n')
        #test.log("build " + self.build) # type: ignore
        logger.info("build " + self.build)
        self.version = getRegistryValue_cmd_version(
            r"SOFTWARE\Elekta Oncology Systems Ltd\RTD", "DisplayedVersion", ip_addr, int(port)).strip('\n')
        #test.log("version " + self.version) # type: ignore
        logger.info("version " + self.version)
        self.modkit = getRegistryValue_cmd_version(
            r"SOFTWARE\Elekta Oncology Systems Ltd\RTD", "FullModkitBuild", ip_addr, int(port)).strip('\n')
        if self.modkit in "Could not read registry":
            #test.log("No Modkit installed") # type: ignore
            logger.info("No Modkit installed")
        else:
            #test.log("Modkit installed is " + self.modkit)  # type: ignore
            logger.info("Modkit installed is " + self.modkit)
        self.fkp_asu_with_room_doors_1__open_enabled = getRegistryValue_cmd_version(
            r"SOFTWARE\Elekta Oncology Systems Ltd\RTD\Linac Server",
            "FKP ASU With Room Doors 1 Open Enabled",
            ip_addr,
            int(port)).strip('\n') == "1"
        self.xray_energies = getRegistryValue_cmd_version(
            r"SOFTWARE\Elekta Oncology Systems Ltd\Linac", "XRayEnergies", ip_addr, int(port)).strip('\n')
        self.cabinet = getRegistryValue_cmd_version(
            r"SOFTWARE\Elekta Oncology Systems Ltd\Platform", "Cabinet", ip_addr, int(port)).strip('\n')
        self.nss_ip_address = getRegistryValue_cmd_version(
            r"SOFTWARE\Elekta Oncology Systems Ltd\RTD\NSS", "IP Address", ip_addr, int(port)).strip('\n')
        self.demonstrator = getRegistryValue_cmd_version(
            r"SOFTWARE\Elekta Oncology Systems Ltd\Linac", "Demonstrator", ip_addr, int(port)).strip('\n') == "1"

        # Note: commented out test.logs and replaced with logger.info to remove dependency on squishtest.setTestResult()
        # test.log("Demonstrator check " + str(self.demonstrator))    # type: ignore
        # test.log("Energies " + str(self.xray_energies)) # type: ignore
        # test.log("Cabinet " + str(self.cabinet))    # type: ignore
        # test.log("NSS IP " + str(self.nss_ip_address))  # type: ignore
        # test.log("fkp_asu_with_room_doors_1__open_enabled " + str(self.fkp_asu_with_room_doors_1__open_enabled))    # type: ignore

        logger.info("Demonstrator check " + str(self.demonstrator))
        logger.info("Energies " + str(self.xray_energies))
        logger.info("Cabinet " + str(self.cabinet))
        logger.info("NSS IP " + str(self.nss_ip_address))
        logger.info("fkp_asu_with_room_doors_1__open_enabled " + str(self.fkp_asu_with_room_doors_1__open_enabled))

        self.head_type = self.__get_head_type__(ip_addr, port)
        if self.head_type == "none":
            raise Exception("Registry read failed cannot find head type")
        #test.log("head_type: " + self.head_type)    # type: ignore
        logger.info("head_type: " + self.head_type)

        # Write setup to file
        try:
            with open(os.path.join(r"C:\JenkinsSlave\workspace", "env_var.txt"), "w") as f:
                f.write("Shelter=" + str(self.get_shelter()) + "\n")
                f.write("Build=" + str(self.build) + "\n")
                f.write("Version=" + str(self.version) + "\n")
                if self.modkit in "Could not read registry":
                    f.write("No Modkit installed " + "\n")
                else:
                    f.write("Modkit = " + self.modkit + "\n")
                f.write("Cabinet=" + str(self.cabinet) + "\n")
                f.write("Head=" + str(self.head_type) + "\n")
                f.write("Energies=" + str(self.xray_energies))
        except Exception as e:
            logger.info("Could not write setup to file:-  " + str(e))

    def get_shelter(self):

        if self.linac_id == "2179":
            self.shelter = "C1"
        elif self.linac_id == "6193":
            self.shelter = "C2"
        elif self.linac_id == "4651":
            self.shelter = "D4"
        elif self.linac_id == "6192":
            self.shelter = "D2"
        elif self.linac_id == "1222":
            self.shelter = "D1"
        else:
            self.shelter = "EMU"

        return self.shelter

    # ToT=Yes
    def __get_head_type__(self, ip_addr, port, run_mode="None"):
        try:
            if getRegistryValue_cmd_version(
                r"SOFTWARE\Elekta Oncology Systems Ltd\Linac",
                "MLC_or_MLCiFitted",
                ip_addr,
                    int(port)).strip('\n') == "1":
                return "MLCi"
            elif getRegistryValue_cmd_version(r"SOFTWARE\Elekta Oncology Systems Ltd\Linac", "MLCi2Fitted", ip_addr, int(port)).strip('\n') == "1":
                return "MLCi2"
            elif getRegistryValue_cmd_version(r"SOFTWARE\Elekta Oncology Systems Ltd\Linac", "MLC160Fitted", ip_addr, int(port)).strip('\n') == "1":
                return "MLC160"
            else:
                return "none"
        except Exception:
            return "none"
